mapper.select:
select tr.id, tr.name, tr.type, tr.icc_priv_json, tr.capp_priv_json, tr.admin_priv_json,
       tr.im_org_priv_json, tr.status, tr.gmt_created, tr.gmt_modified
from tb_role tr,
tr_user_role tur
where tr.id = tur.role_id
and tur.user_id = #{userId}

select tr.id, tr.name, tr.type, tr.icc_priv_json, tr.capp_priv_json, tr.admin_priv_json,
       tr.im_org_priv_json, tr.status, tr.gmt_created, tr.gmt_modified
from tb_role tr,
tr_user_role tur,tr_executor_user teu
where tr.id = tur.role_id and tur.user_id=teu.user_id
and teu.executor_id = #{executorId}
